    <script nonce="iCGvBP6mwtnf6MN5Pam8mw">
        (function() {
            var root = document.documentElement, stored = null, mq = null;
            try { stored = localStorage.getItem('cb-theme'); } catch (e) { /* localStorage engelli */ }
            try { mq = window.matchMedia('(prefers-color-scheme: dark)'); } catch (e) {}
            if (stored === 'dark' || stored === 'light') {
                root.setAttribute('data-bs-theme', stored);
            } else if (mq && mq.matches) {
                root.setAttribute('data-bs-theme', 'dark');
            }
            if (mq && mq.addEventListener && stored !== 'dark' && stored !== 'light') {
                mq.addEventListener('change', function(ev) {
                    try { if (localStorage.getItem('cb-theme')) return; } catch (e) {}
                    root.setAttribute('data-bs-theme', ev.matches ? 'dark' : 'light');
                });
            }
        })();
    </script>


