    <style>
        /* === CLARITYBRIEFS BASE STYLES === */

        :root {
            --cb-primary: #5b9aff;
            /* Accessible link/text blue: #5b9aff is only 2.79:1 on white (fails WCAG AA);
               --cb-link is darkened for TEXT on light bg. Backgrounds/icons keep --cb-primary. */
            --cb-link: #2563eb;
            --cb-secondary: #4285f4;
            --cb-gradient: linear-gradient(135deg, #5b9aff 0%, #4285f4 100%);
            --cb-success: #28a745;
            --cb-text: #333;
            --cb-muted: #5c636a;  /* a11y: was #6c757d (fails 4.5:1 on #f8f9fa) */
            --cb-light: #f8f9fa;
            --cb-border: #e9ecef;
            /* Surface tokens (light) */
            --cb-bg: #ffffff;
            --cb-surface: #ffffff;
            --cb-navbar-bg: rgba(255, 255, 255, 0.95);
            --cb-nav-hover-bg: rgba(102, 126, 234, 0.08);
            --cb-shadow: rgba(0, 0, 0, 0.12);
            --cb-shadow-strong: rgba(0, 0, 0, 0.1);
        }

        [data-bs-theme="dark"] {
            --cb-primary: #7ab0ff;
            --cb-link: #7ab0ff;  /* light blue on dark surface = high contrast */
            --cb-secondary: #5294f5;
            --cb-gradient: linear-gradient(135deg, #5b9aff 0%, #4285f4 100%);
            --cb-success: #4cc265;
            --cb-text: #e8eaf0;
            --cb-muted: #9ba3b4;
            --cb-text-muted: #9ba3b4;  /* get_briefings.html var(--cb-text-muted, #6b7280) — aydinlikta tanimsiz, fallback gecer */
            --cb-light: #1a2236;
            --cb-border: #2a3447;
            --cb-bg: #0f1521;
            --cb-surface: #1a2236;
            --cb-navbar-bg: rgba(15, 21, 33, 0.92);
            --cb-nav-hover-bg: rgba(122, 176, 255, 0.12);
            --cb-shadow: rgba(0, 0, 0, 0.5);
            --cb-shadow-strong: rgba(0, 0, 0, 0.4);
        }

        /* Overscroll zemini (2026-07-13): sayfayi yenilemek icin asagi cekince gorunen alan.
           body kendi zeminini boyadigi icin html'in rengi YALNIZ overscroll'da gorunur —
           yani sayfa gorunumu hic degismez, sadece o "lastik" alan markali olur.
           Eskiden orada navbar'in altinda kalmis dil onerisi bandi parliyordu (kaldirildi). */
        html {
            background-color: #4285f4;
        }

        html[data-bs-theme="dark"] {
            background-color: #101827;
        }

        body {
            background-color: var(--cb-bg);
            transition: background-color 0.2s ease, color 0.2s ease;
        }

        /* Dark-mode overrides for hardcoded white/light backgrounds in templates */
        [data-bs-theme="dark"] .bg-white,
        [data-bs-theme="dark"] .bg-light {
            background-color: var(--cb-surface) !important;
            color: var(--cb-text);
        }
        [data-bs-theme="dark"] .card {
            background-color: var(--cb-surface);
            border-color: var(--cb-border);
            color: var(--cb-text);
        }
        [data-bs-theme="dark"] .text-muted {
            color: var(--cb-muted) !important;
        }
        [data-bs-theme="dark"] .border,
        [data-bs-theme="dark"] .border-top,
        [data-bs-theme="dark"] .border-bottom,
        [data-bs-theme="dark"] .border-start,
        [data-bs-theme="dark"] .border-end {
            border-color: var(--cb-border) !important;
        }
        [data-bs-theme="dark"] hr {
            border-color: var(--cb-border);
            opacity: 0.5;
        }
        [data-bs-theme="dark"] .modal-content {
            background-color: var(--cb-surface);
            color: var(--cb-text);
        }
        [data-bs-theme="dark"] .form-control,
        [data-bs-theme="dark"] .form-select {
            background-color: var(--cb-bg);
            border-color: var(--cb-border);
            color: var(--cb-text);
        }
        /* Bootstrap form-select chevron is a baked-in SVG with stroke="#343a40"
           — invisible against a dark surface. Replace with a light-stroke variant. */
        [data-bs-theme="dark"] .form-select {
            background-image: url("data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16'%3e%3cpath fill='none' stroke='%23e8eaf0' stroke-linecap='round' stroke-linejoin='round' stroke-width='2' d='m2 5 6 6 6-6'/%3e%3c/svg%3e");
        }
        [data-bs-theme="dark"] .form-control::placeholder {
            color: var(--cb-muted);
            opacity: 0.7;
        }
        [data-bs-theme="dark"] .list-group-item {
            background-color: var(--cb-surface);
            border-color: var(--cb-border);
            color: var(--cb-text);
        }
        [data-bs-theme="dark"] .table {
            --bs-table-bg: var(--cb-surface);
            --bs-table-color: var(--cb-text);
            --bs-table-border-color: var(--cb-border);
        }
        [data-bs-theme="dark"] .alert-info {
            background-color: rgba(122, 176, 255, 0.15);
            border-color: rgba(122, 176, 255, 0.3);
            color: var(--cb-text);
