        /* Inline style attribute backgrounds — common values that authors hardcode */
        [data-bs-theme="dark"] [style*="background: white"],
        [data-bs-theme="dark"] [style*="background:#fff"],
        [data-bs-theme="dark"] [style*="background: #fff"],
        [data-bs-theme="dark"] [style*="background-color: white"],
