        }
        /* Bootstrap accordion buttons (FAQ pages) */
        [data-bs-theme="dark"] .accordion-button {
            background-color: var(--cb-surface);
            color: var(--cb-text);
        }
        [data-bs-theme="dark"] .accordion-button:not(.collapsed) {
            background-color: var(--cb-bg);
