        }
        /* Section/wrapper background utility — many landing sections use bg-light */
        [data-bs-theme="dark"] section.bg-light,
        [data-bs-theme="dark"] section.bg-white,
        [data-bs-theme="dark"] .section-light,
        [data-bs-theme="dark"] .section-white {
            background-color: var(--cb-surface) !important;
            color: var(--cb-text);
        }
        /* Bootstrap nav-pills/tabs in dark */
        [data-bs-theme="dark"] .nav-pills .nav-link.active,
        [data-bs-theme="dark"] .nav-pills .show > .nav-link {
            background-color: var(--cb-primary);
            color: #fff;
        }
        /* Search/input groups */
        [data-bs-theme="dark"] .input-group-text {
            background-color: var(--cb-bg);
