        }
        /* Cards inside white-bg containers — color text fix */
        [data-bs-theme="dark"] .card-body,
        [data-bs-theme="dark"] .card-title,
        [data-bs-theme="dark"] .card-text {
            color: var(--cb-text);
        }
        [data-bs-theme="dark"] .card-header,
        [data-bs-theme="dark"] .card-footer {
            background-color: var(--cb-bg);
            border-color: var(--cb-border);
            color: var(--cb-text);
        }
        /* Common heading colors set to dark explicitly in templates */
        [data-bs-theme="dark"] h1, [data-bs-theme="dark"] h2,
        [data-bs-theme="dark"] h3, [data-bs-theme="dark"] h4,
        [data-bs-theme="dark"] h5, [data-bs-theme="dark"] h6 {
            color: inherit;
        }
        /* Dropdown items / divider */
        [data-bs-theme="dark"] .dropdown-divider {
            border-color: var(--cb-border);
        }
        [data-bs-theme="dark"] .dropdown-menu {
            background-color: var(--cb-surface);
