        }
        /* Generic content-section cards (legal pages, about, etc.) */
        [data-bs-theme="dark"] .policy-section,
        [data-bs-theme="dark"] .terms-section,
        [data-bs-theme="dark"] .legal-section,
        [data-bs-theme="dark"] .content-card,
        [data-bs-theme="dark"] .info-card,
        [data-bs-theme="dark"] .summary-box,
        [data-bs-theme="dark"] .contact-box,
        [data-bs-theme="dark"] .mission-card,
