        // Global CSRF token for all fetch/AJAX requests
        window.CSRF_TOKEN = document.querySelector('meta[name="csrf-token"]')?.content;

        // Helper function for fetch with CSRF
        window.fetchWithCSRF = function(url, options = {}) {
            options.headers = options.headers || {};
            if (window.CSRF_TOKEN) {
                options.headers['X-CSRFToken'] = window.CSRF_TOKEN;
            }
            return fetch(url, options);
        };

        // Patch native fetch to include CSRF token for same-origin POST/PUT/DELETE
        const originalFetch = window.fetch;
        window.fetch = function(url, options = {}) {
            const method = (options.method || 'GET').toUpperCase();
            if (['POST', 'PUT', 'DELETE', 'PATCH'].includes(method)) {
                options.headers = options.headers || {};
                if (window.CSRF_TOKEN && !options.headers['X-CSRFToken']) {
                    options.headers['X-CSRFToken'] = window.CSRF_TOKEN;
                }
            }
            return originalFetch(url, options);
        };
