        document.addEventListener('DOMContentLoaded', function() {
            var tooltipTriggerList = [].slice.call(document.querySelectorAll('[data-bs-toggle="tooltip"]'));
            tooltipTriggerList.map(function (tooltipTriggerEl) {
                return new bootstrap.Tooltip(tooltipTriggerEl);
            });
        });

        // Theme toggle (light/dark)
        (function() {
            var btn = document.getElementById('themeToggle');
            var icon = document.getElementById('themeToggleIcon');
            var meta = document.getElementById('metaThemeColor');
            if (!btn || !icon) return;

            function applyIcon(theme) {
                icon.classList.toggle('fa-moon', theme === 'light');
                icon.classList.toggle('fa-sun', theme === 'dark');
                if (meta) meta.setAttribute('content', theme === 'dark' ? '#0f1521' : '#5b9aff');
            }
            applyIcon(document.documentElement.getAttribute('data-bs-theme') || 'light');

            btn.addEventListener('click', function() {
                var current = document.documentElement.getAttribute('data-bs-theme') || 'light';
                var next = current === 'dark' ? 'light' : 'dark';
                document.documentElement.setAttribute('data-bs-theme', next);
                try { localStorage.setItem('cb-theme', next); } catch (e) {}
                applyIcon(next);
            });
        })();

        // Language Dropdown: Keyboard navigation (press a letter to jump to matching language)
        (function() {
            var langMenu = document.getElementById('langDropdownMenu');
            if (!langMenu) return;

            var lastKey = '';
            var lastIndex = -1;

            function onKeyDown(e) {
                var key = e.key.toLowerCase();
                if (key.length !== 1 || key < 'a' || key > 'z') return;

                e.preventDefault();
                var items = langMenu.querySelectorAll('a.dropdown-item');
                var matches = [];

                items.forEach(function(item, i) {
                    var name = (item.getAttribute('data-lang-name') || '').toLowerCase();
                    if (name.charAt(0) === key) matches.push(i);
                });

                if (matches.length === 0) return;

                var targetIdx;
                if (key === lastKey && lastIndex >= 0) {
                    // Same key pressed again — cycle to next match
                    var pos = matches.indexOf(lastIndex);
                    targetIdx = matches[(pos + 1) % matches.length];
                } else {
                    targetIdx = matches[0];
                }

                lastKey = key;
                lastIndex = targetIdx;

                var target = items[targetIdx];
                target.focus();
                target.scrollIntoView({ block: 'nearest' });
            }

            var langDropdownEl = document.getElementById('langDropdown');
            if (langDropdownEl) {
                langDropdownEl.parentElement.addEventListener('shown.bs.dropdown', function() {
                    lastKey = '';
                    lastIndex = -1;
                    document.addEventListener('keydown', onKeyDown);
                });
                langDropdownEl.parentElement.addEventListener('hidden.bs.dropdown', function() {
                    document.removeEventListener('keydown', onKeyDown);
                });
            }
        })();

